// rtl/flist/rtl.f — the whole titan-axi DUT (chip_earlgrey_asic with the AXI fabric).
// Paths use ${TITAN_ROOT} (uvm/sim/env.sh sets it).
//
// Order matters only for packages: OpenTitan first (prim_assert.sv defines the
// `ASSERT macros everything uses), then PULP, then ours.

// Earl Grey: every RTL file chip_earlgrey_asic needs, minus the two TL-UL
// crossbars and the vendor top_earlgrey.sv (generated by gen_flist.py).
-f ${TITAN_ROOT}/rtl/flist/earlgrey.f

// tl_peri_pkg is no longer pulled in by xbar_peri; the fabric uses its addresses.
${TITAN_ROOT}/vendor/opentitan/hw/top_earlgrey/ip/xbar_peri/rtl/autogen/tl_peri_pkg.sv

// PULP AXI crossbar + CDC
-f ${TITAN_ROOT}/rtl/vendor/pulp/pulp.f

// titan-axi
${TITAN_ROOT}/rtl/bridge/titan_axi_pkg.sv
${TITAN_ROOT}/rtl/bridge/titan_tlul2axi.sv
${TITAN_ROOT}/rtl/bridge/titan_axi2tlul.sv
${TITAN_ROOT}/rtl/fabric/titan_sim_ctrl.sv
${TITAN_ROOT}/rtl/fabric/titan_axi_fabric.sv
${TITAN_ROOT}/rtl/top/top_earlgrey.sv
